'use strict';
/* public/js/40-fx.js -- dirt particles, item pops, rain, WebAudio sound effects. Generated by scripts/split-client.mjs; see ARCHITECTURE.md. */
/* ---------- dirt particles ---------- */
const PMAX=260;
const pMesh=new T.InstancedMesh(new T.BoxGeometry(0.13,0.13,0.13),M(0xc98f55),PMAX);pMesh.instanceMatrix.setUsage(T.DynamicDrawUsage);pMesh.castShadow=false;pMesh.frustumCulled=false;scene.add(pMesh);
const parts=[];for(let i=0;i<PMAX;i++)parts.push({life:0,x:0,y:0,z:0,vx:0,vy:0,vz:0});let pNext=0;
const dummy=new T.Object3D();
function puff(x,y,z,tx,tz,n){for(let k=0;k<n;k++){const p=parts[pNext];pNext=(pNext+1)%PMAX;const dx=tx-x,dz=tz-z;p.x=x;p.y=y;p.z=z;p.vx=dx*1.1+(Math.random()-0.5)*1.4;p.vz=dz*1.1+(Math.random()-0.5)*1.4;p.vy=3+Math.random()*2.5;p.life=0.9+Math.random()*0.4}}
function updateParts(dt){for(let i=0;i<PMAX;i++){const p=parts[i];if(p.life>0){p.life-=dt;p.vy-=14*dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.z+=p.vz*dt;const g=groundAt(p.x,p.z);if(p.y<g){p.y=g;p.vx*=0.4;p.vz*=0.4;p.vy=0}dummy.position.set(p.x,p.y,p.z);dummy.rotation.set(p.x*3,p.z*3,0);dummy.scale.setScalar(Math.min(1,p.life*2.5))}else dummy.scale.setScalar(0);dummy.updateMatrix();pMesh.setMatrixAt(i,dummy.matrix)}pMesh.instanceMatrix.needsUpdate=true}

/* found-item pop */
const pops=[];
function itemMesh(type){
  if(ITEM_MODELS[type]){const g=ITEM_MODELS[type].clone();g.scale.copy(ITEM_MODELS[type].scale);return g}   // Blender model (23-models.js), once loaded
  const c=LOOT[type].color;
  if(type==='suitcase'){const g=new T.Group();const b=box(0.8,0.55,0.25,c);const h=box(0.3,0.08,0.06,0x2a1a0e);h.position.y=0.32;g.add(b,h);return g}
  if(type==='kb')return cyl(0.06,0.06,0.3,8,c);
  if(type==='shoe'){return new T.Mesh(new T.TorusGeometry(0.16,0.045,5,10,Math.PI*1.5),M(c))}
  if(type==='fossil')return box(0.4,0.08,0.25,c);
  if(type==='jar')return cyl(0.12,0.12,0.24,8,c);
  if(type==='arrow')return new T.Mesh(new T.ConeGeometry(0.1,0.28,3),M(c));
  if(type==='can')return cyl(0.09,0.09,0.2,8,c);
  if(type==='spoon')return box(0.05,0.03,0.3,c);
  if(type==='lipstick')return cyl(0.04,0.04,0.2,8,c);
  if(type==='sploosh')return cyl(0.13,0.11,0.26,8,c);
  if(type==='locket')return new T.Mesh(new T.TorusGeometry(0.1,0.035,6,12),M(c));
  if(type==='pistol'){const g=new T.Group();const b=box(0.32,0.07,0.06,c),h=box(0.07,0.16,0.06,0x5a3a1e);h.position.set(-0.12,-0.08,0);g.add(b,h);return g}
  return cyl(0.07,0.07,0.03,8,c);
}
function popItem(it,hx,hz){const m=itemMesh(it.type);const y=groundAt(hx,hz);m.position.set(hx,y+0.2,hz);scene.add(m);pops.push({m,t:0,y0:y})}
function updatePops(dt){for(let i=pops.length-1;i>=0;i--){const p=pops[i];p.t+=dt;p.m.position.y=p.y0+0.2+Math.sin(Math.min(p.t,1)*Math.PI*0.5)*2.4;p.m.rotation.y+=dt*4;if(p.t>2.2){p.m.scale.multiplyScalar(0.85);if(p.m.scale.x<0.05){scene.remove(p.m);pops.splice(i,1)}}}}

/* Warden's flags around the search area */
const flags=new T.Group();flags.visible=false;scene.add(flags);
for(let i=0;i<14;i++){const a=i/14*Math.PI*2;const x=SEARCH.x+Math.cos(a)*SEARCH.r,z=SEARCH.z+Math.sin(a)*SEARCH.r;const g=new T.Group();const p=cyl(0.04,0.04,1.8,5,0xdcdcdc);p.position.y=0.9;const f=box(0.5,0.3,0.02,0xd12a2a);f.position.set(0.25,1.6,0);g.add(p,f);g.position.set(x,baseH(x,z),z);flags.add(g)}

/* rain */
const RAIN=2200;const rainGeo=new T.BufferGeometry();const rainPos=new Float32Array(RAIN*6);rainGeo.setAttribute('position',new T.BufferAttribute(rainPos,3));
const rain=new T.LineSegments(rainGeo,new T.LineBasicMaterial({color:0xcfe0ee,transparent:true,opacity:0.55}));rain.visible=false;rain.frustumCulled=false;scene.add(rain);
const rainSeed=[];for(let i=0;i<RAIN;i++)rainSeed.push({x:(Math.random()-0.5)*60,y:Math.random()*30,z:(Math.random()-0.5)*60,v:18+Math.random()*8});
function updateRain(dt){if(!rain.visible)return;const cx=camera.position.x,cz=camera.position.z;for(let i=0;i<RAIN;i++){const d=rainSeed[i];d.y-=d.v*dt;if(d.y<-2){d.y=28;d.x=(Math.random()-0.5)*60;d.z=(Math.random()-0.5)*60}const x=cx+d.x,z=cz+d.z,y=d.y+P.y;rainPos.set([x,y,z,x-0.05,y+0.7,z],i*6)}rainGeo.attributes.position.needsUpdate=true}

/* ---------- audio (made in the browser, starts on your first click) ---------- */
let AC=null,master=null,noiseBuf=null,muted=false,rainGain=null;
function initAudio(){
  if(AC)return;try{AC=new (window.AudioContext||window.webkitAudioContext)();master=AC.createGain();master.gain.value=SETTINGS.volMaster;master.connect(AC.destination);
  fxBus=AC.createGain();fxBus.gain.value=SETTINGS.volFx;fxBus.connect(master);   // pause menu: ambient + one-shot sfx share this bus, so Effects volume is independent of Music
  noiseBuf=AC.createBuffer(1,AC.sampleRate*2,AC.sampleRate);const d=noiseBuf.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=Math.random()*2-1;
  const wind=AC.createBufferSource();wind.buffer=noiseBuf;wind.loop=true;const wf=AC.createBiquadFilter();wf.type='lowpass';wf.frequency.value=320;const wg=AC.createGain();wg.gain.value=0.07;
  const lfo=AC.createOscillator();lfo.frequency.value=0.08;const lg=AC.createGain();lg.gain.value=0.04;lfo.connect(lg).connect(wg.gain);lfo.start();
  wind.connect(wf).connect(wg).connect(fxBus);wind.start();
  const rn=AC.createBufferSource();rn.buffer=noiseBuf;rn.loop=true;const rf=AC.createBiquadFilter();rf.type='bandpass';rf.frequency.value=2600;rf.Q.value=0.5;rainGain=AC.createGain();rainGain.gain.value=0;rn.connect(rf).connect(rainGain).connect(fxBus);rn.start();
  }catch(e){AC=null}
}
function noise(dur,freq,q,gain,type){if(!AC)return;const s=AC.createBufferSource();s.buffer=noiseBuf;const f=AC.createBiquadFilter();f.type=type||'bandpass';f.frequency.value=freq;f.Q.value=q;const g=AC.createGain();const t=AC.currentTime;g.gain.setValueAtTime(gain,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);s.connect(f).connect(g).connect(fxBus);s.start(t,Math.random());s.stop(t+dur+0.05)}
function tone(freq,dur,type,gain,to){if(!AC)return;const o=AC.createOscillator();o.type=type||'sine';const g=AC.createGain();const t=AC.currentTime;o.frequency.setValueAtTime(freq,t);if(to)o.frequency.exponentialRampToValueAtTime(to,t+dur);g.gain.setValueAtTime(gain,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);o.connect(g).connect(fxBus);o.start(t);o.stop(t+dur+0.05)}
const sfx={
  scoop(){noise(0.22,420+Math.random()*260,0.7,0.55,'lowpass');tone(110,0.12,'sine',0.25,55)},
  clank(){tone(1400,0.25,'triangle',0.12,900);noise(0.08,3000,3,0.15)},
  find(){[660,880,1320].forEach((f,i)=>setTimeout(()=>tone(f,0.18,'triangle',0.16),i*85))},
  gold(){[523,659,784,1047,1319].forEach((f,i)=>setTimeout(()=>tone(f,0.3,'triangle',0.16),i*110))},
  coin(){tone(988,0.08,'square',0.07);setTimeout(()=>tone(1319,0.18,'square',0.07),70)},
  beep(s){tone(600+s*900,0.06,'square',0.045)},
  hiss(){noise(0.6,4200,1.5,0.22)},
  bite(){noise(0.3,900,1,0.5);tone(200,0.4,'sawtooth',0.18,60)},
  shout(){tone(300,0.15,'sawtooth',0.06,420)},
  splash(){noise(0.4,1200,0.7,0.3)},
  thud(){tone(80,0.2,'sine',0.35,40)}
};

